  "s.diff.noBackup": ["No hay archivo que copiar: se crea.", "There is no file to back up: it is created.", "Não há arquivo para copiar: ele é criado."],
  "s.diff.backupFirst": ["Antes se guarda una copia con fecha: ", "A dated backup is saved first: ", "Antes é salva uma cópia com data: "],
